-- Run this file once in Supabase Dashboard -> SQL Editor.

CREATE TABLE IF NOT EXISTS stations (id varchar(64) PRIMARY KEY, name varchar(128) NOT NULL, base_capacity integer DEFAULT 1, current_worker_id varchar(64), sort_order integer DEFAULT 0);
CREATE TABLE IF NOT EXISTS workers (id varchar(64) PRIMARY KEY, name varchar(128) NOT NULL, prep_time_per_item integer DEFAULT 3, daily_salary integer DEFAULT 0, active integer DEFAULT 1, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS worker_stations (worker_id varchar(64) REFERENCES workers(id) ON DELETE CASCADE, station_id varchar(64) REFERENCES stations(id) ON DELETE CASCADE, prep_time integer DEFAULT 3, PRIMARY KEY (worker_id, station_id));

CREATE TABLE IF NOT EXISTS menu_items (id varchar(64) PRIMARY KEY, name varchar(128) NOT NULL, station_id varchar(64), prep_time integer DEFAULT 5, active integer DEFAULT 1, image_path varchar(255), food_type varchar(20) DEFAULT 'non-veg', category varchar(32) DEFAULT 'others', sort_order integer DEFAULT 0);
CREATE TABLE IF NOT EXISTS menu_variants (id varchar(64) PRIMARY KEY, menu_item_id varchar(64) REFERENCES menu_items(id) ON DELETE CASCADE, name varchar(64), price numeric(10,2) DEFAULT 0, recipe_multiplier numeric(10,4) DEFAULT 1);
CREATE TABLE IF NOT EXISTS menu_recipes (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, menu_item_id varchar(64) REFERENCES menu_items(id) ON DELETE CASCADE, ingredient_id varchar(64), ingredient_type varchar(32), quantity numeric(10,4), unit varchar(32), UNIQUE (menu_item_id, ingredient_id));

CREATE TABLE IF NOT EXISTS raw_ingredients (id varchar(64) PRIMARY KEY, name varchar(128) NOT NULL, stock numeric(10,2) DEFAULT 0, reserved numeric(10,2) DEFAULT 0, min_stock numeric(10,2) DEFAULT 0, purchase_unit varchar(32), stock_unit varchar(32), conversion_factor numeric(10,4) DEFAULT 1, cost_per_purchase_unit numeric(10,2) DEFAULT 0, supplier varchar(128));
CREATE TABLE IF NOT EXISTS intermediate_stock (id varchar(64) PRIMARY KEY, name varchar(128) NOT NULL, stock numeric(10,2) DEFAULT 0, reserved numeric(10,2) DEFAULT 0, min_stock numeric(10,2) DEFAULT 0, unit varchar(32), item_type varchar(32) DEFAULT 'intermediate');
CREATE TABLE IF NOT EXISTS batch_recipes (id varchar(64) PRIMARY KEY, name varchar(128) NOT NULL, unit varchar(32), expected_yield_ratio numeric(10,4) DEFAULT 1, processing_type varchar(64), fuel_type varchar(32) DEFAULT 'none', fuel_cost numeric(10,2) DEFAULT 0);
CREATE TABLE IF NOT EXISTS batch_recipe_ingredients (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, batch_recipe_id varchar(64), raw_ingredient_id varchar(64), ratio_per_unit numeric(10,4), unit varchar(32), UNIQUE (batch_recipe_id, raw_ingredient_id));

CREATE TABLE IF NOT EXISTS orders (id varchar(64) PRIMARY KEY, customer_name varchar(128), source varchar(32), priority varchar(32), subtotal numeric(10,2), tax numeric(10,2), total numeric(10,2), commission numeric(10,2), net_revenue numeric(10,2), eta integer, fulfillment_status varchar(32), payment_status varchar(32), created_at timestamptz DEFAULT now(), ts_active timestamptz, ts_queued timestamptz, ts_accepted timestamptz, ts_cooking timestamptz, ts_ready timestamptz, ts_completed timestamptz);
CREATE TABLE IF NOT EXISTS order_items (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id varchar(64) REFERENCES orders(id) ON DELETE CASCADE, menu_item_id varchar(64), menu_item_name varchar(128), variant_id varchar(64), variant_name varchar(64), quantity integer, unit_price numeric(10,2), modifiers jsonb DEFAULT '[]'::jsonb, status varchar(32), type varchar(32) DEFAULT 'DINE_IN', is_new integer DEFAULT 0);
CREATE TABLE IF NOT EXISTS expenses (id varchar(64) PRIMARY KEY, expense_date date, item_name varchar(128), quantity numeric(10,2), unit varchar(32), cost numeric(10,2), supplier varchar(128), raw_ingredient_id varchar(64), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, log_timestamp timestamptz DEFAULT now(), actor varchar(80) DEFAULT 'System Admin', action varchar(80), payload text);
CREATE TABLE IF NOT EXISTS day_history (id varchar(64) PRIMARY KEY, report_date date, order_count integer, revenue numeric(10,2), expenses numeric(10,2), net_profit numeric(10,2), source_breakdown jsonb, item_sales jsonb, inventory_snapshot jsonb, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS egg_tracking (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tracking_date date UNIQUE, opening_stock integer DEFAULT 0, purchased integer DEFAULT 0, rotten integer DEFAULT 0, used_in_prep integer DEFAULT 0, used_in_menu integer DEFAULT 0, closing_stock integer DEFAULT 0, recommended_price numeric(10,2) DEFAULT 0);
CREATE TABLE IF NOT EXISTS custom_expense_items (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, item_name varchar(128) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS custom_suppliers (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, supplier_name varchar(128) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS daily_reports (report_date date PRIMARY KEY, order_count integer DEFAULT 0, revenue numeric(10,2) DEFAULT 0, expenses numeric(10,2) DEFAULT 0, net_profit numeric(10,2) DEFAULT 0);
